const wchar_t *TranslateExtra(const wchar_t *zh, Lang lang) {
    if (!zh) return nullptr;
    for (int i = 0; i < ROW_COUNT; ++i) {
        if (wcscmp(ROWS[i].zh, zh) != 0) continue;
        switch (lang) {
        case Lang::ZhHant: return ROWS[i].zhHant;
        case Lang::Ja:     return ROWS[i].ja;
        case Lang::Ko:     return ROWS[i].ko;
        default:           return nullptr;
        }
    }
    return nullptr;
}

